import React from 'react';

export default function LmsDashboard({ username, onLogout }) {
  const teachers = [
    { id: 1, name: 'Mr. Perera', subject: 'Mathematics' },
    { id: 2, name: 'Ms. Silva', subject: 'Science' }
  ];

  const students = [
    { id: 1, name: 'Kamal Perera', class: 'Grade 10' },
    { id: 2, name: 'Nimal Silva', class: 'Grade 11' }
  ];

  return (
    <div style={{ padding: '40px', backgroundColor: '#f4f7f6', minHeight: '100vh', fontFamily: 'Arial, sans-serif' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
        <h1>Admin Dashboard</h1>
        <button onClick={onLogout} style={{ padding: '10px 20px', backgroundColor: '#d32f2f', color: '#fff', border: 'none', borderRadius: '5px', cursor: 'pointer' }}>Logout</button>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '30px' }}>
        {/* Teachers Table */}
        <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 10px rgba(0,0,0,0.1)' }}>
          <h3>Manage Teachers</h3>
          <table style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse' }}>
            <thead><tr style={{ borderBottom: '2px solid #eee' }}><th>Name</th><th>Subject</th><th>Action</th></tr></thead>
            <tbody>
              {teachers.map(t => (
                <tr key={t.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '15px 0' }}>{t.name}</td>
                  <td style={{ padding: '15px 0' }}>{t.subject}</td>
                  <td><button style={{ cursor: 'pointer' }}>Edit</button></td>
                </tr>
              ))}
            </tbody>
          </table>
          <button style={{ marginTop: '20px', width: '100%', padding: '10px' }}>Add New Teacher</button>
        </div>

        {/* Students Table */}
        <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 10px rgba(0,0,0,0.1)' }}>
          <h3>Manage Students</h3>
          <table style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse' }}>
            <thead><tr style={{ borderBottom: '2px solid #eee' }}><th>Name</th><th>Class</th><th>Action</th></tr></thead>
            <tbody>
              {students.map(s => (
                <tr key={s.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '15px 0' }}>{s.name}</td>
                  <td style={{ padding: '15px 0' }}>{s.class}</td>
                  <td><button style={{ cursor: 'pointer' }}>Edit</button></td>
                </tr>
              ))}
            </tbody>
          </table>
          <button style={{ marginTop: '20px', width: '100%', padding: '10px' }}>Add New Student</button>
        </div>
      </div>
    </div>
  );
}
